import * as THREE from 'three/webgpu';
import { texture, uv, positionLocal, vec3, float, uniform, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-stat-tile';
  group.position.set(-1.25, 0.7, 0);

  const colorMap = ctx.textureLoader.load(config.assets?.imageUrl ?? '/prism-mock/home/nodes/parallax-stack.png');
  const depthMap = ctx.textureLoader.load(config.assets?.depthMapUrl ?? '/prism-mock/home/nodes/parallax-stack.depth.png');

  const geometry = new THREE.PlaneGeometry(1.5, 0.9, 64, 64);

  const displacementStrength = uniform(0.05);
  const hoverLift = uniform(0.0);
  const focusAccent = uniform(0.0);

  const depthSample = texture(depthMap, uv()).r;
  const displaced = positionLocal.add(
    vec3(0.0, 0.0, depthSample.sub(0.5).mul(displacementStrength))
  ).add(vec3(0.0, hoverLift, 0.0));

  const material = new THREE.MeshStandardNodeMaterial();
  material.positionNode = displaced;
  material.colorNode = mix(
    texture(colorMap, uv()),
    vec3(1.0, 0.164, 0.219),
    focusAccent.mul(0.15)
  );
  material.roughness = 0.55;
  material.metalness = 0.5;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.4;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'stat-tile-surface';
  group.add(mesh);

  // Machined edge frame (accent trim, subtle)
  const edgeGeo = new THREE.PlaneGeometry(1.54, 0.94);
  const edgeMat = new THREE.MeshStandardNodeMaterial();
  edgeMat.colorNode = vec3(0.086, 0.086, 0.114);
  edgeMat.metalness = 0.4;
  edgeMat.roughness = 0.6;
  const edge = new THREE.Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.001;
  group.add(edge);

  // Text: metric value + label rendered via MSDF font atlas
  const valueText = ctx.fontAtlas.createText({
    text: '42',
    font: 'Lora',
    weight: 600,
    size: 0.34,
    color: '#e8ecf2',
    atlasIndex: config.atlasRegion?.atlas ?? 0,
  });
  valueText.position.set(-0.55, 0.15, 0.02);
  group.add(valueText);

  const labelText = ctx.fontAtlas.createText({
    text: 'METRIC',
    font: 'JetBrains Mono',
    weight: 700,
    size: 0.09,
    color: '#16161d',
    atlasIndex: config.atlasRegion?.atlas ?? 0,
  });
  labelText.position.set(-0.55, -0.15, 0.02);
  group.add(labelText);

  // Apply cinematic primitives from config
  const primitives = config.cinematicPrimitives || [];
  for (const primitive of primitives) {
    if (ctx.primitives[primitive.name]) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  }

  // Hover / press / focus interaction state
  let hoverTl = null;
  let pressTl = null;

  const onHoverIn = () => {
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(hoverLift, { value: 0.15, duration: 0.4, ease: 'power3.out' });
    hoverTl.to(group.position, { z: group.position.z + 0.05, duration: 0.4, ease: 'power3.out' }, 0);
  };

  const onHoverOut = () => {
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(hoverLift, { value: 0.0, duration: 0.4, ease: 'power3.out' });
    hoverTl.to(group.position, { z: -0.05, duration: 0.4, ease: 'power3.out' }, 0);
  };

  const onClick = () => {
    pressTl?.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.15, ease: 'back.out' });

    if (group.userData.emit) {
      group.userData.emit('hub-features.select', { nodeId: group.name });
    }
  };

  const onFocus = () => {
    gsap.to(focusAccent, { value: 1.0, duration: 0.25, ease: 'power2.out' });
  };

  const onBlur = () => {
    gsap.to(focusAccent, { value: 0.0, duration: 0.25, ease: 'power2.out' });
  };

  group.userData.handlers = {
    hoverIn: onHoverIn,
    hoverOut: onHoverOut,
    click: onClick,
    focus: onFocus,
    blur: onBlur,
  };

  group.userData.cleanup = () => {
    hoverTl?.kill();
    pressTl?.kill();
    geometry.dispose();
    edgeGeo.dispose();
    material.dispose();
    edgeMat.dispose();
    colorMap.dispose?.();
    depthMap.dispose?.();
    valueText.geometry?.dispose?.();
    valueText.material?.dispose?.();
    labelText.geometry?.dispose?.();
    labelText.material?.dispose?.();
  };

  return group;
}
